class SandboxSecurityError(PermissionError):
    """Raised when an operation attempts to access a path outside the allowed sandbox boundary."""
    pass

class SandboxManager:
    """
    Enforces strict path containment rules.
    Prevents path traversal, symlink escapes, and unauthorized directory inspection.
    """
    def __init__(self, allowed_directory: Union[str, Path]):
        self.allowed_directory = Path(allowed_directory).resolve()
        if not self.allowed_directory.exists():
            raise FileNotFoundError(f"Allowed directory does not exist: {self.allowed_directory}")
        if not self.allowed_directory.is_dir():
            raise NotADirectoryError(f"Allowed path is not a directory: {self.allowed_directory}")

    def validate_path(self, target_path: Union[str, Path]) -> Path:
        path_obj = Path(target_path)
        if not path_obj.is_absolute():
            resolved = (self.allowed_directory / path_obj).resolve()
        else:
            resolved = path_obj.resolve()
        try:
            common = Path(os.path.commonpath([str(self.allowed_directory), str(resolved)])).resolve()
            if common != self.allowed_directory:
                raise SandboxSecurityError(f"Access Denied: Path '{target_path}' resolves outside sandbox.")
        except (ValueError, Exception):
            raise SandboxSecurityError(f"Access Denied: Cross-drive or invalid path '{target_path}'.")
        return resolved

class StructuredOutputNode:
    """
    Standardized wrapper around .with_structured_output() featuring an automatic
    repair loop when LLM responses violate the Pydantic schema.
    """
    def __init__(
        self,
        llm: Any,
        schema: Type[T],
        system_prompt: Optional[str] = None,
        max_repairs: int = 2
    ):
        self.llm = llm
        self.schema = schema
        self.system_prompt = system_prompt
        self.max_repairs = max_repairs

    def invoke(self, user_prompt: str, context: Optional[str] = None) -> T:
        messages: List[BaseMessage] = []
        if self.system_prompt:
            messages.append(SystemMessage(content=self.system_prompt))
        user_content = user_prompt if not context else f"{user_prompt}\n\nContext:\n{context}"
        messages.append(HumanMessage(content=user_content))

        attempts = 0
        structured_runner = self.llm.with_structured_output(self.schema)
        while attempts <= self.max_repairs:
            try:
                result = structured_runner.invoke(messages)
                if isinstance(result, self.schema):
                    return result
                return self.schema.model_validate(result)
            except (ValidationError, Exception) as exc:
                attempts += 1
                if attempts > self.max_repairs:
                    raise exc
                repair_prompt = f"Previous response violated schema: {exc}. Please return valid JSON strictly conforming to {self.schema.__name__}."
                messages.append(HumanMessage(content=repair_prompt))

class QANodes:
    """Encapsulates all node logic for the QA subgraph."""
    def __init__(self, services: Optional[ServiceRegistry] = None):
        self.services = services or default_services
        self.router = StructuredOutputNode(
            llm=self.services.llm,
            schema=IntentClassification,
            system_prompt=ROUTER_SYSTEM_PROMPT
        )

    def classify_intent(self, state: QAState) -> Dict[str, Any]:
        """Node 1: Classifies the question into direct, web_search, or rag."""
        query = state["query"]
        try:
            classification: IntentClassification = self.router.invoke(user_prompt=query)
            route = classification.route
        except Exception as e:
            print(f"⚠️ [QA classify_intent] Router fallback to DIRECT: {e}")
            route = RouteDecision.DIRECT

        return {
            "route": route,
            "needs_web_search": (route == RouteDecision.WEB_SEARCH),
        }

