        self._headers = {"Accept": "application/vnd.github.v3+json", "User-Agent": "DevDocsAI-Agent"}
        if self.token:
            self._headers["Authorization"] = f"Bearer {self.token}"

    def _mask_token(self, text: str) -> str:
        """Mask GitHub token in error messages or logs to prevent credential leakage."""
        if not self.token or len(self.token) < 8:
            return text
        masked = self.token[:4] + "***" + self.token[-4:]
