class VectorStoreClient:
    """Wraps Chroma vector store for code snippet retrieval."""
    def __init__(self, persist_directory: Optional[str] = None):
        self.persist_directory = persist_directory or config.chroma_db_dir
        self._vector_store = None
        self._embeddings = None

    def retrieve(self, query: str, k: int = 4) -> List[Dict[str, Any]]:
        """Retrieve top-k relevant code chunks."""
        store = self._get_store()
        if not store:
            return []
        try:
            docs_and_scores = store.similarity_search_with_relevance_scores(query, k=k)
            results = []
            for doc, score in docs_and_scores:
                results.append({
                    "content": doc.page_content,
                    "source_file": doc.metadata.get("source", "unknown"),
                    "score": round(float(score), 4),
                })
            return results
        except Exception as e:
            print(f"⚠️ [VectorStoreClient] Retrieval exception: {e}")
            return []

class SupervisorRouter:
    """Classifies user queries to dispatch to QA, DocGen, or SRS."""
    def __init__(self, services: Optional[ServiceRegistry] = None):
        self.services = services or default_services
        self.node = StructuredOutputNode(
            llm=self.services.llm,
            schema=SupervisorRouteDecision,
            system_prompt=SUPERVISOR_ROUTER_SYSTEM_PROMPT
        )

    def route(self, query: str, context: Optional[str] = None) -> SupervisorRouteDecision:
        """Determines the target route for a query."""
        try:
            decision: SupervisorRouteDecision = self.node.invoke(user_prompt=query, context=context)
            return decision
        except Exception as e:
            print(f"⚠️ [SupervisorRouter] Fallback to QA: {e}")
            return SupervisorRouteDecision(
                target_subagent="qa",
                reasoning="Fallback due to routing error",
                extracted_repo_url=None,
                extracted_local_path=None
            )

class ClarificationNodes:
    def check_completeness(self, state: ClarificationState) -> Dict[str, Any]:
        """Node 2: Evaluates IEEE 830 requirement completeness."""
        reqs = state["requirements"]
        turn_count = state.get("turn_count", 0)
        max_turns = state.get("max_turns", 3)

        completeness: CompletenessCheck = self.completeness_checker.invoke(
            user_prompt=f"RequirementsModel:\n{json.dumps(reqs.model_dump(), indent=2)}"
        )

        # Force complete if turn limit reached to prevent infinite clarification loops
        if turn_count >= max_turns:
            completeness.is_complete = True
            completeness.next_question = None

        return {"completeness": completeness}

